import unittest
from counter import Counter
class Contract(unittest.TestCase):
    def test_retry(self):
        c=Counter(); self.assertEqual(c.apply("a", 2), 2); self.assertEqual(c.apply("a", 2), 2)
    def test_conflict(self):
        c=Counter(); c.apply("a", 2)
        with self.assertRaises(ValueError): c.apply("a", 3)
        self.assertEqual(c.value, 2)
    def test_zero(self):
        c=Counter(); c.apply("a", 0)
        with self.assertRaises(ValueError): c.apply("a", 1)
    def test_independent(self):
        c=Counter(); c.apply("a", 2); self.assertEqual(c.apply("b", 3), 5)

