class Counter:
    def __init__(self):
        self.value = 0
        self.seen = {}
    def apply(self, request_id, amount):
        if request_id in self.seen:
            if self.seen[request_id] != amount:
                raise ValueError("conflicting retry")
            return self.value
        self.value += amount
        self.seen[request_id] = amount
        return self.value
